function twoSum(array $nums, int $target): ?array {
    $seen = [];                         // value => index
    foreach ($nums as $i => $n) {
        $need = $target - $n;
        if (array_key_exists($need, $seen)) {
            return [$seen[$need], $i];
        }
        $seen[$n] = $i;
    }
    return null;
}
// twoSum([2, 7, 11, 15], 9) → [0, 1]   O(n) time, O(n) space

