function allPairs(array $nums, int $target): array {
    $seen = []; $out = [];          // value => [indexes]
    foreach ($nums as $i => $n) {
        foreach ($seen[$target - $n] ?? [] as $j) $out[] = [$j, $i];
        $seen[$n][] = $i;
    }
    return $out;
}
// O(n) average; output size can be large but each pair is found once.
